def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_count = 0
    rich_aggressive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if isinstance(prev, dict) else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 100 and opp.get('budget', 0) >= 150:
                    rich_aggressive += 1

    if not alive_opponents:
        return max(0.0, min(float(budget), 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    units = int(supply / WATER_REQ)
    if units < 1:
        units = 1
    competitors = len(alive_opponents) + 1
    scarcity = competitors - units

    critical_self = hp <= 3 or no_water_days >= 2
    pressured_self = hp <= 5 or no_water_days >= 1

    if critical_self:
        target = max(0.92 * DAILY_SALARY, highest_prev + 3.0)
        if scarcity >= 3:
            target = max(target, 1.18 * DAILY_SALARY)
        return max(0.0, min(float(budget), float(target)))

    if supply >= 24 and hp >= 7 and no_water_days == 0:
        target = 12.0
        if urgent_count >= 2:
            target = 20.0
        return max(0.0, min(float(budget), float(target)))

    if supply <= 16:
        target = highest_prev + 2.5 if highest_prev > 0 else 88.0
        if rich_aggressive >= 2:
            target += 8.0
        if pressured_self:
            target += 10.0
        return max(0.0, min(float(budget), float(target)))

    if scarcity >= 3:
        target = max(82.0, highest_prev + 2.0)
        if pressured_self:
            target += 8.0
        return max(0.0, min(float(budget), float(target)))

    if scarcity == 2:
        if highest_prev >= 110:
            target = 46.0 if not pressured_self else 92.0
        else:
            target = max(58.0, avg_prev + 1.5)
        return max(0.0, min(float(budget), float(target)))

    if scarcity == 1:
        if pressured_self:
            target = max(60.0, highest_prev * 0.72)
        else:
            target = 34.0 if highest_prev >= 100 else 42.0
        return max(0.0, min(float(budget), float(target)))

    target = 18.0
    if day >= 8 and hp >= 6:
        target = 10.0
    if pressured_self:
        target = 36.0
    return max(0.0, min(float(budget), float(target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for agent_id, st in opponents_status.items():
        if st.get('alive', False):
            alive_opps.append((agent_id, st))

    if not alive_opps:
        # Conservative fallback
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids to infer their aggressiveness
    prev_bids = []
    for _, st in alive_opps:
        prev = st.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # If no trace info, use supply-based baseline
    if not prev_bids:
        if supply <= float(MIN_SUPPLY):
            target = DAILY_SALARY * 0.65
        else:
            target = DAILY_SALARY * 0.55
    else:
        highest_prev_bid = max(prev_bids)
        avg_prev_bid = sum(prev_bids) / float(len(prev_bids))

        # Their survival with high bids suggests a competitive market.
        # If they were bidding near/above salary, bid in that neighborhood.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if hp <= 2 or no_water_days >= 2:
                target = DAILY_SALARY * 0.95
            else:
                target = DAILY_SALARY * 0.70
        else:
            # Otherwise, slightly over average to maintain a competitive edge.
            target = max(avg_prev_bid + 2.0, DAILY_SALARY * 0.55)

        # Supply pressure: with higher supply, we can shade down a bit.
        # With lower supply, shade up.
        if supply <= float(WATER_REQ):
            target *= 1.10
        elif supply <= float(MIN_SUPPLY):
            target *= 1.05
        elif supply >= float(MAX_SUPPLY):
            target *= 0.95

    # Budget/hp risk management
    if hp <= 1 or no_water_days >= 3:
        # Must secure water
        cap = DAILY_SALARY * 1.05
    elif hp <= 3 or no_water_days >= 2:
        cap = DAILY_SALARY * 0.85
    else:
        cap = DAILY_SALARY * 0.75

    # Additional guard: never bid above what we can afford
    bid = min(budget, cap, target)

    # Ensure non-negative and at least small positive when budget allows
    if bid < 1.0 and budget >= 1.0:
        bid = min(budget, 1.0)

    return float(bid)
